def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 > v2:
        result = "2018"
    elif v2 > v1:
        result = "2019"
    else:
        result = "Both 2018 and 2019"

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "comparison": "v1 > v2" if v1 > v2 else ("v2 > v1" if v2 > v1 else "v1 == v2"),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
